\label{anti-slant}
Let $\widetilde{M}$ be a Riemannian manifold endowed with an anti-torqued vector field $V$, and let $\gamma \subset \widetilde{M}$ be a Frenet curve of order $r$, $1\leq r \leq m$. If $\gamma$ is an anti-torqued slant helix with axis $V$, then one the following holds:
\begin{enumerate}
\item[(a)] $\gamma$ is a geodesic in $\widetilde{M}$,

\item[(b)] $\gamma$ is a Frenet curve of order $2$, the conformal scalar of $V$ is the negative of the first curvature of $\gamma$, and $V$ is a concircular vector field along $\gamma$,

\item[(c)] $\gamma$ satisfies the system \eqref{sys-anti}.
\end{enumerate}

Let $\gamma \subset \widetilde{M}$ be a Frenet curve of order $r$, $1\leq r \leq m$, parametrized by arc-length. Denote by $(T^\gamma,N_2^\gamma,...,N_m^\gamma)$ the Frenet frame of $\gamma$, and by $\kappa_i$, for $0<j<m-1$, the curvatures of $\gamma$.

If $\gamma$ is an anti-torqued slant helix with axis $V$, then from Definition \ref{def} it follows
\begin{equation*}
\langle V , N_2^\gamma \rangle = \cos \theta , \quad \theta \in [0,2\pi].
\end{equation*}
We distinguish three cases:

{\bf Case 1.} $V$ is parallel to $T^\gamma$ along $\gamma$. Then $\theta = \frac{\pi}{2}$ (or $\theta = \frac{3\pi}{2}$) and  $V=\pm T^\gamma$. Without lose of generality, we may assume $V=T^\gamma$, meaning that $\gamma$ is the integral curve of $V$. Since $V$ is a unit geodesic vector field on $\widetilde{M}$, $\gamma$ becomes a geodesic in $\widetilde{M}$.

{\bf Case 2.} $V$ is parallel to one of $N_2^\gamma,...,N_m^\gamma$ along $\gamma$. Without lose of generality, we may assume $V=N_i^\gamma$, for $2\leq i \leq m$. Because $V$ is an anti-torqued vector field on $\widetilde{M}$, we have
$$
\widetilde{\nabla}_{T^\gamma} N_i^\gamma= \rho T^\gamma.
$$
On the other hand, the Frenet equations give
$$
\widetilde{\nabla}_{T^\gamma} N_i^\gamma=
\left\{
\begin{array}{cc}
-\kappa_1T^\gamma +\kappa_{2} N_{3}^\gamma,&  i=2,\\
-\kappa_{i-1} N_{i-1}^\gamma +\kappa_{i} N_{i+1}^\gamma,& 2<i<m, \\
-\kappa_{m-1} N_m^\gamma,& i=m.
\end{array} 
\right.
$$
Comparing these expressions, we conclude that the only possible case is $i=2$ and $\kappa_1=-\rho$. Consequently, it follows that $\theta \in \{0,\pi,2\pi\} $ and the set
$$
\{T^\gamma , \widetilde{\nabla}_{T^\gamma} T^\gamma,  \widetilde{\nabla}_{T^\gamma}(\widetilde{\nabla}_{T^\gamma} T^\gamma)  \}
$$
is linearly dependent, which means that $\gamma$ is a Frenet curve of order $2$, and the conformal scalar $\rho$ along $\gamma$ is equal to $-\kappa_1$. Moreover, $V$ is a concircular vector field along $\gamma$.

{\bf Case 3.}
$V$ is parallel to none of $T^\gamma,N_2^\gamma,...,N_m^\gamma$ along $\gamma$. Thus, $V$ admits the following orthogonal decomposition:
\begin{equation}
V= f_1^\gamma T^\gamma +\cos \theta N_2^\gamma +\sum_{i=3}^m f_i^\gamma N_i^\gamma, \label{anti-1}
\end{equation}
where $f_1^\gamma, f_3^\gamma,...,f_m^\gamma$ are smooth functions defined on $I$. Since $V$ is anti-torqued, it follows that
$$
\widetilde{\nabla}_{T^\gamma} V = \rho(T^\gamma-f_1^\gamma V),
$$
where the relation $\langle V,T^\gamma \rangle =f_1^\gamma$ has been used. Expanding this expression yields
$$
\widetilde{\nabla}_{T^\gamma} V = \rho \left ( (1-(f_1^\gamma)^2)T^\gamma -\cos \theta f_1^\gamma  N_2^\gamma -f_1^\gamma \sum_{i=3}^m f_i^\gamma N_i^\gamma\right ).
$$
Moreover, derivating \eqref{anti-1} with respect to $T^{\gamma }$ and applying the Frenet formulas, we conclude that
\begin{eqnarray*}
\widetilde{\nabla}_{T^\gamma} V &=&(T^{\gamma }(f_{1}^{\gamma })-\cos \theta \kappa_{1})T^{\gamma }+(\kappa _{1}f_{1}^{\gamma }-\kappa _{2}f_{3}^{\gamma})N_{2}^{\gamma }
\\
&&+(T^{\gamma }(f_{3}^{\gamma })+\cos \theta \kappa_{2}-\kappa _{3}f_{4}^{\gamma })N_{3}^{\gamma}
\\
&&+\sum_{i=4}^{m-1}(T^{\gamma }(f_{i}^{\gamma })+\kappa _{i-1}f_{i-1}^{\gamma}-\kappa _{i}f_{i+1}^{\gamma })N_{i}^{\gamma }
\\
&&+(T^{\gamma }(f_{m}^{\gamma})+\kappa _{m-1}f_{m-1}^{\gamma })N_{m}^{\gamma }.
\end{eqnarray*}
By equating the tangent and normal components in the last two relations, we obtain
\begin{equation}
\left.
\begin{array}{l}
T^{\gamma }(f_{1}^{\gamma })-\cos \theta \kappa_{1} -\rho  ( 1-(f_1^\gamma)^2)=0, \\
\kappa _{1}f_{1}^{\gamma }-\kappa _{2}f_{3}^{\gamma}+\cos \theta \rho f_1^\gamma =0, \\
T^{\gamma }(f_{3}^{\gamma })+\cos \theta \kappa_{2}-\kappa _{3}f_{4}^{\gamma }+\rho f_1^\gamma f_3^\gamma=0,\\
T^{\gamma }(f_{i}^{\gamma })+\kappa _{i-1}f_{i-1}^{\gamma}-\kappa _{i}f_{i+1}^{\gamma }+\rho f_1^\gamma f_i^\gamma=0, \quad 4\leq i \leq m-1,\\
T^{\gamma }(f_{m}^{\gamma})+\kappa _{m-1}f_{m-1}^{\gamma }+\rho f_1^\gamma f_m^\gamma=0.
\end{array} 
\right.  \label{sys-anti}
\end{equation}

\label{exm-zero-tors}
Let $\widetilde{M}=\mathbb R^3\backslash \{0\}$, and let $(x,y,z)$ denote the Cartesian coordinates. Consider the logarithmic spiral lying in the $xz$-plane (see Figure \ref{fig1})
$$
\gamma (s)=\frac{s}{\sqrt{2}}\left( \cos \left( \log s\right) ,0,\sin \left( \log s\right) \right) , \quad s>0,
$$ 
with curvature $\kappa(s)=\frac{1}{s}$. The conformal scalar of the anti-torqued vector field $V=\frac{E}{|E| } $ along $\gamma$ is
$$
\rho|_{\gamma(s)}=\frac{1}{|\gamma(s)|}=\frac{\sqrt{2}}{s}, \quad s>0,
$$
where $E$ is the radial vector field in $\mathbb R^3$. A direct calculation shows that the angle between $V$ and $N^\gamma$ along $\gamma$ is $\theta =\frac{3\pi}{4}$ (or $\theta =\frac{7\pi}{4}$), and that
$$
f^\gamma(s)=\frac{1}{\sqrt{2}}, \quad g^\gamma(s)=0.
$$
It is easy to verify that the system \eqref{sys-anti-3} is satisfied.
\begin{figure}[hbtp]
\begin{center}
\includegraphics[width=.3\textwidth]{fig1.pdf} \includegraphics[width=.2\textwidth]{fig2.pdf}
\end{center}
\caption{Left: Logaritmic spiral as an anti-torqued slant helix. Right: Loxodrome as an anti-torqued slant helix.}\label{fig1}
\end{figure}

\label{anti-slant2}
Let $E$ be the radial vector field in $\widetilde{M}=\mathbb R^3\backslash\{0\}$, and let $\gamma \subset\widetilde{M}$ be a Frenet curve of order $r$, $1\leq r \leq 3$. If $\gamma$ is an anti-torqued slant helix with axis $\frac{E}{|E|}$, then one the following holds:
\begin{enumerate}
\item[(a)]  $\gamma$ is a circle with centered at the origin, lying an affine plane of
$\widetilde{M}$ that passes through the origin,

\item[(b)]  $\gamma$ is a logaritmic spiral lying an affine plane of $\widetilde{M}$,

\item[(c)]  $\gamma$ is a rectifying curve in $\widetilde{M}$,

\item[(d)]  $\gamma$ satisfies Equations \eqref{kappa} and \eqref{tau}.
\end{enumerate}

Let $V=\frac{E}{|E|}$ be an anti-torqued vector field on $\widetilde{M}=\mathbb R^3\backslash\{0\}$, with conformal scalar $\rho=\frac{1}{|E|}$. Assume that $\gamma=\gamma(s)$, $s\in I$, is an anti-torqued slant helix with axis $V$, parametrized by arc-length. Since  $V|_\gamma=\frac{\gamma}{|\gamma|}$, we have
$$
\langle \gamma(s), N^\gamma(s)\rangle=\phi(s)\cos \theta,
$$
where $N^\gamma$ is the principal normal vector field of $\gamma$, and $\phi(s)=|\gamma(s)|$ is the distance function of $\gamma(s)$. If $\theta=\frac{\pi}{2}$ (or $\theta=\frac{3\pi}{2}$), then the above expression characterizes rectifying curves. We will assume that $\theta\notin \{\frac{\pi}{2},\frac{3\pi}{2}\}$. Derivating $\phi(s)$, we obtain
$$
\phi (s)\phi '(s)=\langle \gamma (s),T^{\gamma}(s)\rangle.
$$
Thus, the following orthogonal decomposition of $\gamma(s)$ holds:
\begin{equation}
\gamma (s)=\phi (s)\phi'(s)T^{\gamma }(s)+\cos \theta \phi
(s)N^{\gamma }(s)+g(s)B^{\gamma }(s),  \label{frame}
\end{equation} 
where $g(s)$ is a smooth function on the interval $I$. Derivating Equation \eqref{frame}, we conclude that
\begin{equation}
\left.
\begin{array}{r}
\left( \phi (s)\phi'(s)\right)'-\cos \theta \phi (s)\kappa
(s)-1=0, \\
\left( \cos \theta +\kappa (s)\phi (s)\right) \phi'(s)-g(s)\tau (s)=0,
\\
g^{\prime }(s)+\cos \theta \phi (s)\tau (s)=0. 
\end{array} 
\right.  \label{sys}
\end{equation}
To solve the system \eqref{sys}, we consider two cases:

{\bf Case:} Assume that $\tau (s)=0,$ for every $s \in I$. In this case, \eqref{frame} and \eqref{sys} reduce, respectively, to
\begin{equation}
\gamma (s)=\phi (s)\phi ^{\prime }(s)T^{\gamma }(s)+\cos \theta  \phi
(s)N^{\gamma }(s)  \label{TN}
\end{equation} 
and 
\begin{equation}
\left.
\begin{array}{r}
\left( \phi (s)\phi ^{\prime }(s)\right) ^{\prime }-\cos \theta  \kappa (s)\phi
(s)-1=0, \\
\left( \cos \theta +\kappa (s)\phi (s)\right) \phi ^{\prime }(s)=0. 
\end{array} 
\right.  \label{sys-tau=0}
\end{equation}
If $\phi (s)$ is a positive constant, which is equivalent to saying that $\gamma (s)$ is a circle centered at the origin, then from Equation \eqref{TN}, we have $\cos \theta =\pm 1$.  However, from the first equality of the system \eqref{sys-tau=0}, we deduce $\cos \theta =- 1$. If $\phi' (s)\neq 0$ for every $s,$ then $\cos \theta =-\kappa (s)\phi (s)$. On the other hand, because $\left\langle \gamma (s),\gamma (s)\right\rangle =\phi (s)^{2},$ from
Equation \eqref{TN} we have $\phi'(s)=\pm \sin \theta. $ Integrating this expression, we obtain
$$
\phi (s)=\pm \sin \theta s+c,
$$
for a constant $c.$ Moreover,
$$
\kappa (s)=-\frac{\cos \theta }{\pm \sin \theta s+c},
$$
which corresponds to a logarithmic spiral \cite[p. 138]{gr}.

{\bf Case:} Suppose that $\tau (s)\neq 0$ for every $s \in I.$ From the system \eqref{sys}, we conclude that
\begin{equation}
\kappa (s)=\frac{\left( \phi (s)\phi ^{\prime }(s)\right) ^{\prime }-1}{ 
\cos \theta \phi (s)}  \label{kappa}
\end{equation} 
and
\begin{equation}
\tau ^{\prime }(s)=\frac{\tau (s)}{F(s)}\left( F^{\prime }(s)+(\cos \theta ) ^{2}\phi
(s)\tau (s)^{2}\right) ,   \label{tau}
\end{equation} 
where $F(s)=\left( (\cos \theta ) ^{2}+\left( \phi (s)\phi'(s)\right)
^{\prime }-1\right) \phi'(s).$

\label{tor-slant}
Let $\widetilde{M}$ be a Riemannian manifold endowed with a torqued vector field $V$, and let $\gamma \subset \widetilde{M}$ be a Frenet curve of order $r$, $1\leq r \leq m$. If $\gamma$ is a torqued curve with respect to $V$, then one the following holds:
\begin{enumerate}
\item[(a)] $\gamma$ is a geodesic in $\widetilde{M}$, and $V$ is a concircular vector field along $\gamma$,

\item[(b)] $\gamma$ is a Frenet curve of order $2$, the conformal scalar of $V$ is a multiple of the first curvature of $\gamma$, and $V$ is a concircular vector field along $\gamma$,

\item[(c)] $\gamma$ satisfies the system \eqref{sys-tor}.
\end{enumerate}

If $\gamma(s)$, $s\in I$, is a torqued curve with respect to $V$, then it follows that
\begin{equation*}
\langle V , N_2^\gamma \rangle = \theta , \quad \theta \in \mathbb R.
\end{equation*}
We consider three cases:

{\bf Case 1.} $V$ is parallel to $T^\gamma$ along $\gamma$. Then $\theta =0 $ and  $V=f^\gamma T^\gamma$ with $f^\gamma$ a smooth function on $I$. Since $\omega(T)=0$, we have $\widetilde{\nabla}_{T^\gamma}V=\rho T^\gamma$. On the other hand, differentiating $V=f^\gamma T^\gamma$ along $\gamma$ gives
$$
\widetilde{\nabla}_{T^\gamma}V=T^\gamma(f^\gamma)T^\gamma+f^\gamma \kappa_1 N_2^\gamma.
$$
Comparing these expressions, we deduce that $T^\gamma(f^\gamma)=\rho$ and $\kappa_1\equiv 0$, because $V$ is nowhere zero on $\widetilde{M}$.

{\bf Case 2.} $V$ is parallel to one of $N_2^\gamma,...,N_m^\gamma$ along $\gamma$. Without lose of generality, we may assume $V=f_i^\gamma N_i^\gamma$, $2\leq i \leq m$, for a smooth function $f_i^\gamma$ on $I$. Because $\omega(N_i^\gamma)=0$, we have
$$
\widetilde{\nabla}_{T^\gamma} (f_i^\gamma N_i^\gamma)= \rho T^\gamma.
$$
On the other hand, the Frenet equations imply that
$$
\widetilde{\nabla}_{T^\gamma} (f_i^\gamma N_i^\gamma)=
\left\{
\begin{array}{cc}
T^\gamma(f_2^\gamma)N_2^\gamma-f_2^\gamma\kappa_1T^\gamma +f_2^\gamma\kappa_{2} N_{3}^\gamma,&  i=2,\\
T^\gamma(f_i^\gamma)N_i^\gamma-f_i^\gamma\kappa_{i-1} N_{i-1}^\gamma +f_i^\gamma\kappa_{i} N_{i+1}^\gamma,& 2<i<m, \\
T^\gamma(f_m^\gamma)N_i^\gamma-f_m^\gamma\kappa_{m-1} N_m^\gamma,& i=m.
\end{array} 
\right.
$$
Similar to the proof of Theorem \ref{anti-slant}, comparing these expressions, we conclude that it must be $i=2$, $\kappa_1f_2^\gamma=-\rho$, $\kappa_2\equiv0$, and $T^\gamma(f_2^\gamma)=0$. Moreover, $V$ is a concircular vector field along $\gamma$.

{\bf Case 3.}
$V$ is parallel to none of $T^\gamma,N_2^\gamma,...,N_m^\gamma$ along $\gamma$. Let $W$ be generative of $V$. Thus, there exist smooth functions $f_1^\gamma,f_3^\gamma,...,f_m^\gamma$ and $g_1^\gamma,g_2^\gamma,...,g_m^\gamma$ defined on $I$ such that
\begin{equation}
V= f_1^\gamma T^\gamma + \theta N_2^\gamma +\sum_{i=3}^m f_i^\gamma N_i^\gamma, \label{torq-1}
\end{equation}
and
\begin{equation}
W= g_1^\gamma T^\gamma + \sum_{i=2}^m g_i^\gamma N_i^\gamma. \label{torq-2}
\end{equation}
Since $V$ is a torqued vector field, we have
$$
\widetilde{\nabla}_{T^\gamma} V = \rho(T^\gamma+g_1^\gamma V).
$$
Expanding this expression yields
$$
\widetilde{\nabla}_{T^\gamma} V = \rho \left ( (1+f_1^\gamma g_1^\gamma)T^\gamma + \theta  g_1^\gamma  N_2^\gamma +g_1^\gamma \sum_{i=3}^m f_i^\gamma N_i^\gamma\right ).
$$
Derivating \eqref{torq-1} with respect to $T^{\gamma }$, we get
\begin{eqnarray*}
\widetilde{\nabla}_{T^\gamma} V &=&(T^{\gamma }(f_{1}^{\gamma })- \theta \kappa_{1})T^{\gamma }+(\kappa _{1}f_{1}^{\gamma }-\kappa _{2}f_{3}^{\gamma})N_{2}^{\gamma }
\\
&&+(T^{\gamma }(f_{3}^{\gamma })+ \theta \kappa_{2}-\kappa _{3}f_{4}^{\gamma })N_{3}^{\gamma}
\\
&&+\sum_{i=4}^{m-1}(T^{\gamma }(f_{i}^{\gamma })+\kappa _{i-1}f_{i-1}^{\gamma}-\kappa _{i}f_{i+1}^{\gamma })N_{i}^{\gamma }
\\
&&+(T^{\gamma }(f_{m}^{\gamma})+\kappa _{m-1}f_{m-1}^{\gamma })N_{m}^{\gamma }.
\end{eqnarray*}
From the last two relations and $\langle V,W \rangle =0$, we obtain
\begin{equation}
\left.
\begin{array}{l}
T^{\gamma }(f_{1}^{\gamma })- \theta \kappa_{1} -\rho  ( 1+f_1^\gamma g_1^\gamma)=0, \\
\kappa _{1}f_{1}^{\gamma }-\kappa _{2}f_{3}^{\gamma}+\theta \rho g_1^\gamma =0, \\
T^{\gamma }(f_{3}^{\gamma })+\theta \kappa_{2}-\kappa _{3}f_{4}^{\gamma }+\rho f_3^\gamma g_1^\gamma=0,\\
T^{\gamma }(f_{i}^{\gamma })+\kappa _{i-1}f_{i-1}^{\gamma}-\kappa _{i}f_{i+1}^{\gamma }+\rho  f_i^\gamma g_1^\gamma=0, \quad 4\leq i \leq m-1,\\
T^{\gamma }(f_{m}^{\gamma})+\kappa _{m-1}f_{m-1}^{\gamma }+\rho  f_m^\gamma g_1^\gamma=0, \\
f_1^\gamma g_1^\gamma +\theta g_2^\gamma +\sum_{i=3}^m f_i^\gamma g_i^\gamma =0.
\end{array} 
\right.  \label{sys-tor}
\end{equation}
